package acn

import "encoding/json"

// AccessStatusDocument is generated by Runtime, not signed by an Agent. Its
// authority is the NAS security context and the Agent/SUPI binding at ACF.
type AccessStatusDocument struct {
	AgentID   string `json:"agent_id"`
	Status    string `json:"status"`
	Timestamp string `json:"timestamp"`
	Reason    string `json:"reason"`
}

type AgentAccessStatusReport struct {
	messageMarker
	Header
	AccessStatus json.RawMessage
}

func (*AgentAccessStatusReport) MessageType() MessageType { return MessageTypeAgentAccessStatusReport }
func (*AgentAccessStatusReport) Direction() Direction     { return Uplink }

type AgentAccessStatusAccept struct {
	messageMarker
	Header
}

func (*AgentAccessStatusAccept) MessageType() MessageType { return MessageTypeAgentAccessStatusAccept }
func (*AgentAccessStatusAccept) Direction() Direction     { return Downlink }

type AccessStatusRejectCause uint8

const (
	AccessStatusRejectInvalidReport AccessStatusRejectCause = iota + 1
	AccessStatusRejectProfileNotFound
	AccessStatusRejectBindingMismatch
	AccessStatusRejectStaleReport
	AccessStatusRejectInternalError
)

func (c AccessStatusRejectCause) String() string {
	switch c {
	case AccessStatusRejectInvalidReport:
		return "INVALID_REPORT"
	case AccessStatusRejectProfileNotFound:
		return "PROFILE_NOT_FOUND"
	case AccessStatusRejectBindingMismatch:
		return "BINDING_MISMATCH"
	case AccessStatusRejectStaleReport:
		return "STALE_REPORT"
	case AccessStatusRejectInternalError:
		return "INTERNAL_ERROR"
	default:
		return "UNKNOWN"
	}
}

type AgentAccessStatusReject struct {
	messageMarker
	Header
	Cause AccessStatusRejectCause
}

func (*AgentAccessStatusReject) MessageType() MessageType { return MessageTypeAgentAccessStatusReject }
func (*AgentAccessStatusReject) Direction() Direction     { return Downlink }

func (c *Codec) encodeAccessStatus(output *encoder, message *AgentAccessStatusReport) error {
	if err := validateJSONObject(message.AccessStatus, "access_status", c.limits.MaxJSONContainer); err != nil {
		return err
	}
	output.lve(message.AccessStatus)
	return nil
}
func (c *Codec) decodeAccessStatus(input *decoder, header Header) (Message, error) {
	value, err := input.lveBytes("access_status", c.limits.MaxJSONContainer)
	if err != nil {
		return nil, err
	}
	if err := validateJSONObject(value, "access_status", c.limits.MaxJSONContainer); err != nil {
		return nil, err
	}
	return &AgentAccessStatusReport{Header: header, AccessStatus: cloneBytes(value)}, nil
}
func encodeAccessStatusReject(output *encoder, message *AgentAccessStatusReject) error {
	if message.Cause < AccessStatusRejectInvalidReport || message.Cause > AccessStatusRejectInternalError {
		return newProtocolError(ErrorCodeInvalidValue, "reject_cause", -1, ErrInvalidValue)
	}
	output.uint8(uint8(message.Cause))
	return nil
}
func decodeAccessStatusReject(input *decoder, header Header) (Message, error) {
	cause, err := input.uint8("reject_cause")
	if err != nil {
		return nil, err
	}
	message := &AgentAccessStatusReject{Header: header, Cause: AccessStatusRejectCause(cause)}
	if err := encodeAccessStatusReject(&encoder{}, message); err != nil {
		return nil, err
	}
	return message, nil
}
